  Lemma y4f_step : forall k prev mm ws (x8 x9 x12 x13 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x31 : word),
    0 <= k < 4 -> Y4M mm SPS ws -> nth_error ws 13 = Some (Z_to_bv 64 SS) -> WSOK ws k -> DST <= prev <= DST + dcap ->
    (forall SE mm' ws' (x9' a2' a3' x18' x19' x20' x21' x24' x25' x26' x27' : word),
       Y4M mm' SPS ws' -> nth_error ws' 13 = Some (Z_to_bv 64 SS) -> WSOK ws' (k + 1) -> DST <= SE <= DST + dcap ->
       evt psegs POST (MS (mkR (Z_to_bv 64 (SP + -192)) (Z_to_bv 64 (SP + -416)) gp tp (Z_to_bv 64 8) (Z_to_bv 64 k) (Z_to_bv 64 seg)
             (Z_to_bv 64 (SP + -224 + 8 * k)) x9' (Z_to_bv 64 (DT + 4)) (Z_to_bv 64 SE) a2' a3' (Z_to_bv 64 0x104d0)
             (Z_to_bv 64 (SP + -136)) (Z_to_bv 64 (SP + -256)) (Z_to_bv 64 DBC) x18' x19' x20' x21'
             (Z_to_bv 64 SS) (Z_to_bv 64 (SS + 8)) x24' x25' x26' x27' (Z_to_bv 64 64) (Z_to_bv 64 2) (Z_to_bv 64 4) (Z_to_bv 64 SE))
        F (Z_to_bv 64 0x15f18) fc None mm' (seg_rom psegs))) ->
    evt psegs POST (KH 0x15a50 mm k prev x8 x9 x12 x13 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x31).
